INSERT INTO wiki_unit (id, faction_id, sort, name, name_ko, category, role, tier, recruit_building, recruit_building_ko, cost, upkeep, unit_cap, scarce_input, squad_size, hp, melee_attack, melee_defence, weapon_strength, armour, missile_damage, range, ammo, speed, leadership, attributes, counters, equipment, equipment_ko, appearance, appearance_ko, gdd_ref) VALUES ('arc-baptised-duelist-escort', 'arc', 10, 'Baptised Duelist Escort', '세례 결투 호위대', 'commander', 'champion', 3, 'House Guard Yard', '가문 호위 마당', 1000, 250, 4, 'implants', 8, 118, 52, 36, 50, 45, NULL, NULL, NULL, 36, 72, '["baptised","plate-biter","thin-clad"]', '["arc-clan-levy-cleavers","arc-clan-levy-hooks","arc-field-fitters"]', 'Short heavy blades swung from machine-replaced forearms, and a small round shield strapped to the other arm. Each escort keeps spare joints in oilcloth and a small heated case for parts that cannot freeze.', '기계로 바꾼 아래팔로 짧고 무거운 칼을 휘두르고 반대 팔에는 작은 둥근 방패를 묶는다. 호위마다 기름천에 싼 예비 관절과, 얼면 안 되는 부품을 넣는 작은 보온 상자를 지닌다.', 'Three thin layers: a short coat cut open at the shoulders and knees, insulating sleeves strapped tight over each implant, and a red house sash. The part count is stitched on the right collar, one bar for each part.', '얇은 세 겹이다. 어깨와 무릎을 터서 짧게 자른 외투를 입고, 이식 부위마다 단열 토시를 가죽끈으로 바짝 여미며, 붉은 가문 띠를 두른다. 오른쪽 깃에 부위 하나마다 줄 하나씩 부위 수를 수놓는다.', NULL);
INSERT INTO wiki_unit (id, faction_id, sort, name, name_ko, category, role, tier, recruit_building, recruit_building_ko, cost, upkeep, unit_cap, scarce_input, squad_size, hp, melee_attack, melee_defence, weapon_strength, armour, missile_damage, range, ammo, speed, leadership, attributes, counters, equipment, equipment_ko, appearance, appearance_ko, gdd_ref) VALUES ('arc-clan-head-guard', 'arc', 20, 'Clan Head''s Guard', '가문 수장 호위대', 'commander', 'command', 4, 'House Seat Hall', '가문 본청', 1800, 450, 3, 'implants', 10, 126, 55, 46, 55, 70, NULL, NULL, NULL, 34, 84, '["baptised","roll-call","thin-clad","last-to-leave"]', '["arc-clan-levy-hooks","arc-house-shield-bearers","arc-warm-bench-aid-crews"]', 'Long-hafted war axes and heavy short shields, carried by warriors with replaced arms and legs. A cell pack on each back feeds the limbs through insulated cable, and the field fitter walks one pace behind.', '자루가 긴 전투 도끼와 무거운 짧은 방패를 든다. 팔다리를 바꾼 전사들이며, 등의 전지 꾸러미가 단열 전선으로 부위를 먹이고, 야전 정비공이 한 걸음 뒤에서 따른다.', 'Two layers: a fitted dark coat opened at every joint that carries a part, over a knitted undershirt. The clan mark is stitched at the left collar and the part count at the right, and on the surface a heated wrap goes over the implants.', '두 겹이다. 뜨개 속옷 위에 부위가 있는 이음매마다 틈을 낸, 몸에 맞춘 짙은 외투를 입는다. 왼쪽 깃에 가문 표지를, 오른쪽 깃에 부위 수를 수놓고, 지상에서는 이식 부위 위에 데운 감싸개를 두른다.', NULL);
INSERT INTO wiki_unit (id, faction_id, sort, name, name_ko, category, role, tier, recruit_building, recruit_building_ko, cost, upkeep, unit_cap, scarce_input, squad_size, hp, melee_attack, melee_defence, weapon_strength, armour, missile_damage, range, ammo, speed, leadership, attributes, counters, equipment, equipment_ko, appearance, appearance_ko, gdd_ref) VALUES ('arc-hierophant-escort', 'arc', 30, 'Hierophant''s Escort', '교주 호위대', 'commander', 'command', 5, 'Hierophant''s Guard Hall', '교주 호위청', 2900, 725, 1, 'implants', 12, 135, 62, 56, 58, 85, NULL, NULL, NULL, 36, 96, '["baptised","thin-clad","iron-dread","last-to-leave"]', '["arc-clan-levy-cleavers","arc-house-shield-bearers","arc-net-casting-crews"]', 'Paired short blades and a long hooked staff for pulling attackers off their feet, carried by the most heavily fitted warriors in the Arc. They guard one person and take no other duty.', '짧은 칼 한 쌍과, 덤비는 자를 넘어뜨리는 갈고리 달린 긴 장대를 든다. 아크에서 부위를 가장 많이 단 전사들이며, 한 사람만 지키고 다른 임무는 맡지 않는다.', 'Two light layers of wool and salvaged synthetic, cut close to the body and open at every part. Insulating sleeves in house red cover the implants, and the collar bars run in rows too long to count at a glance.', '몸에 붙게 자른 얇은 모직과 건져 온 합성 섬유 두 겹이다. 부위마다 틈이 있고, 붉은 가문 색 단열 토시가 이식 부위를 덮으며, 깃의 줄이 한눈에 셀 수 없을 만큼 길게 이어진다.', NULL);
INSERT INTO wiki_unit (id, faction_id, sort, name, name_ko, category, role, tier, recruit_building, recruit_building_ko, cost, upkeep, unit_cap, scarce_input, squad_size, hp, melee_attack, melee_defence, weapon_strength, armour, missile_damage, range, ammo, speed, leadership, attributes, counters, equipment, equipment_ko, appearance, appearance_ko, gdd_ref) VALUES ('arc-clan-levy-hooks', 'arc', 40, 'Clan Levy Hooks', '가문 징집 갈고리병', 'infantry', 'line', 1, 'House Muster Hall', '가문 집결소', 200, 42, NULL, NULL, 50, 72, 24, 24, 26, 12, NULL, NULL, NULL, 34, 45, '["house-bound","charge-breaker"]', '["arc-clan-sled-raiders","arc-levy-ski-scouts"]', 'Long hooked poles for pulling riders off sleds, and a short blade. There are no firearms, and each levy brings a felt-lined pot helmet of his own.', '썰매에서 사람을 끌어내리는 긴 갈고리 장대와 짧은 칼을 든다. 화기는 없고, 투구는 각자 가져온 펠트 댄 냄비 철모다.', 'Five layers: a felt overcoat over a quilted jacket, quilted trousers, wrapped boots and a hood tied under the chin, with a clan-coloured band on the upper arm.', '다섯 겹이다. 누빔 저고리 위에 펠트 외투를 입고, 누빈 바지에 감싼 장화를 신고, 턱 밑에서 묶는 두건을 쓰며, 위팔에 가문 색 띠를 맨다.', NULL);
INSERT INTO wiki_unit (id, faction_id, sort, name, name_ko, category, role, tier, recruit_building, recruit_building_ko, cost, upkeep, unit_cap, scarce_input, squad_size, hp, melee_attack, melee_defence, weapon_strength, armour, missile_damage, range, ammo, speed, leadership, attributes, counters, equipment, equipment_ko, appearance, appearance_ko, gdd_ref) VALUES ('arc-clan-levy-cleavers', 'arc', 50, 'Clan Levy Cleavers', '가문 징집 도끼병', 'infantry', 'shock', 1, 'House Muster Hall', '가문 집결소', 230, 48, NULL, NULL, 40, 69, 28, 14, 34, 8, NULL, NULL, NULL, 36, 40, '["house-bound"]', '["arc-clan-levy-carbines","arc-clan-crossbow-skirmishers"]', 'Broad cleaving axes cut down from tunnel tools and swung with both hands. A vest of scrap plate covers the chest and nothing else.', '터널 연장을 잘라 만든 넓은 날 도끼를 두 손으로 휘두른다. 고철판 조끼가 가슴만 가려 준다.', 'Four layers: a quilted coat, a felt overcoat with the sleeves tied back, padded trousers and wrapped boots, with a scrap-plate vest over all and a clan band on the upper arm.', '네 겹이다. 누빔 웃옷과, 소매를 걷어 묶은 펠트 외투, 솜바지, 감싼 장화를 입고 그 위에 고철판 조끼를 걸치며, 위팔에 가문 색 띠를 맨다.', NULL);
INSERT INTO wiki_unit (id, faction_id, sort, name, name_ko, category, role, tier, recruit_building, recruit_building_ko, cost, upkeep, unit_cap, scarce_input, squad_size, hp, melee_attack, melee_defence, weapon_strength, armour, missile_damage, range, ammo, speed, leadership, attributes, counters, equipment, equipment_ko, appearance, appearance_ko, gdd_ref) VALUES ('arc-house-shield-bearers', 'arc', 60, 'House Shield Bearers', '가문 방패병', 'infantry', 'line', 2, 'House Muster Hall', '가문 집결소', 480, 100, NULL, NULL, 40, 80, 26, 44, 22, 45, NULL, NULL, NULL, 30, 56, '["house-bound","shield-line"]', '["arc-clan-levy-carbines","arc-clan-crossbow-skirmishers","arc-warm-bench-aid-crews"]', 'Tall shields riveted together from door panels, and short spears for the second rank. The front rank sets the shields edge to edge across a tunnel mouth.', '문짝을 리벳으로 이어 만든 키 큰 방패와, 둘째 줄이 쓰는 짧은 창을 든다. 앞줄은 굴 입구를 가로질러 방패 가장자리를 맞대 세운다.', 'Four layers: a felt overcoat, quilted trousers, wrapped boots and a pressed-steel helmet lined with felt, with a clan band on the upper arm and the house colour painted on the shield face.', '네 겹이다. 펠트 외투, 누빈 바지, 감싼 장화를 입고 펠트를 댄 눌러 편 철판 투구를 쓰며, 위팔에 가문 색 띠를 맨고 방패 겉면에 가문 색을 칠한다.', NULL);
INSERT INTO wiki_unit (id, faction_id, sort, name, name_ko, category, role, tier, recruit_building, recruit_building_ko, cost, upkeep, unit_cap, scarce_input, squad_size, hp, melee_attack, melee_defence, weapon_strength, armour, missile_damage, range, ammo, speed, leadership, attributes, counters, equipment, equipment_ko, appearance, appearance_ko, gdd_ref) VALUES ('arc-house-hatch-breakers', 'arc', 70, 'House Hatch Breakers', '가문 해치 돌파병', 'infantry', 'breacher', 2, 'House Muster Hall', '가문 집결소', 560, 120, NULL, NULL, 24, 82, 30, 22, 48, 28, NULL, NULL, NULL, 33, 55, '["house-bound","breach-charge"]', '["arc-net-casting-crews","arc-warm-bench-aid-crews"]', 'Sledgehammers, pry bars and satchels of hand charges for forcing hatches and barricades. They carry no ranged weapon.', '해치와 방벽을 여는 큰 망치, 지렛대, 손 폭약 주머니를 든다. 원거리 무기는 없다.', 'Four layers: a quilted coat under a leather apron, padded trousers and wrapped boots, with goggles pushed up on a felt cap and a clan band on the upper arm.', '네 겹이다. 누빔 웃옷 위에 가죽 앞치마를 두르고, 솜바지에 감싼 장화를 신으며, 펠트 모자 위로 보안경을 밀어 올리고 위팔에 가문 색 띠를 맨다.', NULL);
INSERT INTO wiki_unit (id, faction_id, sort, name, name_ko, category, role, tier, recruit_building, recruit_building_ko, cost, upkeep, unit_cap, scarce_input, squad_size, hp, melee_attack, melee_defence, weapon_strength, armour, missile_damage, range, ammo, speed, leadership, attributes, counters, equipment, equipment_ko, appearance, appearance_ko, gdd_ref) VALUES ('arc-baptised-hammer-arms', 'arc', 80, 'Baptised Hammer Arms', '세례 망치팔대', 'infantry', 'shock', 3, 'Baptism Training Hall', '세례 수련장', 1100, 275, 4, 'implants', 20, 118, 50, 32, 56, 52, NULL, NULL, NULL, 34, 70, '["baptised","plate-biter","thin-clad","iron-dread"]', '["arc-clan-levy-carbines","arc-clan-sled-raiders"]', 'Heavy breaching hammers swung by machine-replaced arms, with a plate strapped over the chest. Each warrior carries a small kit of spare joints for the replaced parts.', '기계로 바꾼 팔로 무거운 돌파 망치를 휘두르며 가슴에 판을 묶는다. 전사마다 바꾼 부위에 맞는 예비 관절 꾸러미를 지닌다.', 'Three thin layers: a knitted undershirt, a fitted coat left open at the replaced arm, and a red sash. The metal of the arm shows at the cuff, tight insulating sleeves cover the joints on the surface, and the part count is stitched on the right collar.', '얇은 세 겹이다. 뜨개 속옷 위에 바꾼 팔 쪽을 터 놓은 맞춤 외투를 입고 붉은 띠를 두르며, 소매 끝으로 팔의 쇠가 보이고, 지상에서는 단열 토시가 이음매를 바짝 덮는다. 오른쪽 깃에 부위 수를 수놓는다.', NULL);
INSERT INTO wiki_unit (id, faction_id, sort, name, name_ko, category, role, tier, recruit_building, recruit_building_ko, cost, upkeep, unit_cap, scarce_input, squad_size, hp, melee_attack, melee_defence, weapon_strength, armour, missile_damage, range, ammo, speed, leadership, attributes, counters, equipment, equipment_ko, appearance, appearance_ko, gdd_ref) VALUES ('arc-baptised-spike-arms', 'arc', 90, 'Baptised Spike Arms', '세례 쐐기팔대', 'infantry', 'anti-armour', 3, 'Baptism Training Hall', '세례 수련장', 1150, 290, 4, 'implants', 20, 118, 40, 30, 60, 50, NULL, NULL, NULL, 33, 68, '["baptised","plate-biter","machine-hunter","thin-clad"]', '["arc-clan-crossbow-skirmishers","arc-levy-ski-scouts"]', 'Armoured forearms ending in drive spikes for punching through plate and hull, with a short shield on the free arm. A cell pack on the back feeds the arms through insulated cable.', '판금과 차체를 뚫는 쐐기 달린 갑옷 아래팔을 쓰고, 남은 팔에는 짧은 방패를 든다. 등의 전지 꾸러미가 단열 전선으로 두 팔을 먹인다.', 'Three thin layers: a short coat open at both shoulders over a knitted vest, with insulated cable running from the pack to each arm. The part count is painted on the helmet.', '얇은 세 겹이다. 뜨개 조끼 위에 양어깨를 터 놓은 짧은 외투를 입고, 단열 전선이 등짐에서 두 팔로 이어지며, 철모에 부위 수를 칠한다.', NULL);
INSERT INTO wiki_unit (id, faction_id, sort, name, name_ko, category, role, tier, recruit_building, recruit_building_ko, cost, upkeep, unit_cap, scarce_input, squad_size, hp, melee_attack, melee_defence, weapon_strength, armour, missile_damage, range, ammo, speed, leadership, attributes, counters, equipment, equipment_ko, appearance, appearance_ko, gdd_ref) VALUES ('arc-baptised-clan-guard', 'arc', 100, 'Baptised Clan Guard', '세례 가문 호위병', 'infantry', 'line', 4, 'Baptism Guard Hall', '세례 호위청', 1700, 430, 3, 'implants', 24, 128, 54, 52, 52, 80, NULL, NULL, NULL, 33, 82, '["baptised","house-bound","thin-clad","last-to-leave"]', '["arc-clan-levy-carbines","arc-baptised-eye-marksmen","arc-field-fitters"]', 'Long swords and tower shields carried by warriors with replaced arms and legs, the line that holds when a levy breaks. A field fitter marches with every squad, with a tool roll and spare joints.', '긴 칼과 큰 방패를 든 팔다리를 바꾼 전사들이며, 징집병이 무너질 때 버티는 전열이다. 분대마다 야전 정비공이 연장 두루마리와 예비 관절을 들고 함께 행군한다.', 'Two layers: a fitted dark coat with flapped openings at each joint over a knitted vest. The clan mark is stitched at the left collar, and the part count at the right collar and painted on the helmet.', '두 겹이다. 뜨개 조끼 위에 이음매마다 덮개 틈을 낸 몸에 맞춘 짙은 외투를 입는다. 왼쪽 깃에 가문 표지를 수놓고, 오른쪽 깃에 부위 수를 수놓으며 철모에도 칠한다.', NULL);
INSERT INTO wiki_unit (id, faction_id, sort, name, name_ko, category, role, tier, recruit_building, recruit_building_ko, cost, upkeep, unit_cap, scarce_input, squad_size, hp, melee_attack, melee_defence, weapon_strength, armour, missile_damage, range, ammo, speed, leadership, attributes, counters, equipment, equipment_ko, appearance, appearance_ko, gdd_ref) VALUES ('arc-refitted-guard-warriors', 'arc', 110, 'Refitted Guard Warriors', '완전 이식 호위 전사', 'infantry', 'shock', 4, 'Baptism Guard Hall', '세례 호위청', 1900, 475, 2, 'implants', 20, 132, 56, 56, 58, 90, NULL, NULL, NULL, 36, 88, '["baptised","thin-clad","iron-dread","plate-biter"]', '["arc-clan-sled-raiders","arc-baptised-eye-marksmen","arc-levy-ski-scouts"]', 'Two-handed cutting blades on fully refitted arms, and plated legs that let them cross a tunnel at a run. The field fitter counts out their spare joints before every march.', '완전히 바꾼 팔로 두 손 절단 검을 휘두르고, 굴 하나를 달려 건너게 해 주는 판 입힌 다리를 쓴다. 행군 전마다 정비공이 이들의 예비 관절을 세어 준다.', 'Two light layers cut close and open at every joint, with insulating sleeves in house red. The collar bars run in long rows, and the part count is painted large on each helmet.', '몸에 붙게 자르고 이음매마다 틈을 낸 얇은 두 겹이다. 붉은 가문 색 단열 토시를 끼고, 깃의 줄이 길게 이어지며, 철모마다 부위 수를 크게 칠한다.', NULL);
INSERT INTO wiki_unit (id, faction_id, sort, name, name_ko, category, role, tier, recruit_building, recruit_building_ko, cost, upkeep, unit_cap, scarce_input, squad_size, hp, melee_attack, melee_defence, weapon_strength, armour, missile_damage, range, ammo, speed, leadership, attributes, counters, equipment, equipment_ko, appearance, appearance_ko, gdd_ref) VALUES ('arc-clan-levy-carbines', 'arc', 120, 'Clan Levy Carbines', '가문 징집 기병총반', 'missile', 'rifle', 1, 'House Muster Hall', '가문 집결소', 260, 55, NULL, 'ammo', 24, 69, 14, 14, 18, 5, 22, 145, 12, 33, 42, '["house-bound"]', '["arc-clan-levy-hooks","arc-clan-levy-cleavers"]', 'Bolt-action carbines of mixed origin and a sack for recovered brass. The station office counts out the rounds one by one before a march.', '출처가 제각각인 볼트식 기병총과 회수한 탄피를 담는 자루를 든다. 행군 전에 역 사무소가 탄을 한 발씩 세어 준다.', 'Four layers: a felt overcoat, quilted trousers and wrapped boots, with a hood under a surplus helmet and a clan band on the upper arm.', '네 겹이다. 펠트 외투, 누빈 바지, 감싼 장화를 입고, 옛 잉여 철모 아래 두건을 쓰며, 위팔에 가문 색 띠를 맨다.', NULL);
INSERT INTO wiki_unit (id, faction_id, sort, name, name_ko, category, role, tier, recruit_building, recruit_building_ko, cost, upkeep, unit_cap, scarce_input, squad_size, hp, melee_attack, melee_defence, weapon_strength, armour, missile_damage, range, ammo, speed, leadership, attributes, counters, equipment, equipment_ko, appearance, appearance_ko, gdd_ref) VALUES ('arc-clan-crossbow-skirmishers', 'arc', 130, 'Clan Crossbow Skirmishers', '가문 석궁 산개병', 'missile', 'skirmish', 2, 'House Muster Hall', '가문 집결소', 520, 110, NULL, NULL, 24, 72, 16, 18, 20, 15, 28, 120, 14, 36, 52, '["house-bound","muscle-powered","scout-deploy"]', '["arc-clan-levy-hooks","arc-house-hatch-breakers"]', 'Hand-spanned crossbows with a quiver of bolts that are picked up and used again, and a short knife. They need no powder.', '손으로 당기는 석궁과 주워서 다시 쓰는 화살 통, 짧은 칼을 든다. 화약은 필요 없다.', 'Four layers: a quilted coat under a felt overcoat, padded trousers and wrapped boots, with a hood tied under the chin and a clan band on the upper arm.', '네 겹이다. 누빔 웃옷 위에 펠트 외투를 입고, 솜바지에 감싼 장화를 신으며, 턱 밑에서 묶는 두건을 쓰고 위팔에 가문 색 띠를 맨다.', NULL);
INSERT INTO wiki_unit (id, faction_id, sort, name, name_ko, category, role, tier, recruit_building, recruit_building_ko, cost, upkeep, unit_cap, scarce_input, squad_size, hp, melee_attack, melee_defence, weapon_strength, armour, missile_damage, range, ammo, speed, leadership, attributes, counters, equipment, equipment_ko, appearance, appearance_ko, gdd_ref) VALUES ('arc-baptised-eye-marksmen', 'arc', 140, 'Baptised Eye Marksmen', '세례 눈 저격조', 'missile', 'marksman', 3, 'House Guard Yard', '가문 호위 마당', 1000, 250, 4, 'implants,ammo', 12, 90, 18, 20, 22, 25, 52, 190, 10, 34, 66, '["baptised","thin-clad","quiet-step"]', '["arc-clan-head-guard","arc-baptised-duelist-escort","arc-clan-levy-hooks"]', 'Long scoped rifles fired by marksmen with a replaced eye and a steadied arm, each carrying a few counted rounds. A small heated case keeps the eye parts from freezing between shots.', '눈 하나와 팔 하나를 바꾼 저격수가 긴 조준경 소총을 쏘며, 저마다 센 탄 몇 발만 지닌다. 작은 보온 상자가 쏘는 사이 눈 부품이 얼지 않게 지켜 준다.', 'Three thin layers: a short coat open at the shoulders, a knitted hood under the helmet and a clan-coloured insulating sleeve over the replaced arm. The part count is stitched on the right collar and painted on the helmet.', '얇은 세 겹이다. 어깨를 터 놓은 짧은 외투를 입고, 철모 아래 뜨개 두건을 쓰며, 바꾼 팔 위에 가문 색 단열 토시를 낀다. 오른쪽 깃에 부위 수를 수놓고 철모에도 칠한다.', NULL);
INSERT INTO wiki_unit (id, faction_id, sort, name, name_ko, category, role, tier, recruit_building, recruit_building_ko, cost, upkeep, unit_cap, scarce_input, squad_size, hp, melee_attack, melee_defence, weapon_strength, armour, missile_damage, range, ammo, speed, leadership, attributes, counters, equipment, equipment_ko, appearance, appearance_ko, gdd_ref) VALUES ('arc-levy-ski-scouts', 'arc', 150, 'Levy Ski Scouts', '징집 스키 정찰병', 'fast', 'recon', 1, 'House Muster Hall', '가문 집결소', 220, 46, NULL, NULL, 12, 90, 18, 20, 20, 8, NULL, NULL, NULL, 64, 42, '["house-bound","frost-hardened","scout-deploy","quiet-step"]', '["arc-clan-levy-carbines","arc-warm-bench-aid-crews"]', 'Long skis with leather bindings, climbing spikes, a short knife and a signal lantern. They scout ahead of the column and fall back on the main line.', '가죽끈 묶음쇠가 달린 긴 스키와 등반 쐐기, 짧은 칼, 신호 등을 지닌다. 행렬 앞을 정찰하다가 본대로 물러난다.', 'Six layers for the surface: a quilted jacket and felt overcoat over a wool undershirt, padded trousers, wrapped felt boots, a hood under an ear-flap cap and a white outer smock, with a clan band on the upper arm.', '지상용 여섯 겹이다. 양모 속옷 위에 누빔 저고리와 펠트 외투를 입고, 솜바지와 감싼 펠트 장화를 신으며, 귀덮개 모자 아래 두건을 쓰고 흰 겉옷을 걸치며, 위팔에 가문 색 띠를 맨다.', NULL);
INSERT INTO wiki_unit (id, faction_id, sort, name, name_ko, category, role, tier, recruit_building, recruit_building_ko, cost, upkeep, unit_cap, scarce_input, squad_size, hp, melee_attack, melee_defence, weapon_strength, armour, missile_damage, range, ammo, speed, leadership, attributes, counters, equipment, equipment_ko, appearance, appearance_ko, gdd_ref) VALUES ('arc-clan-sled-raiders', 'arc', 160, 'Clan Sled Raiders', '가문 썰매 습격대', 'fast', 'raider', 2, 'House Muster Hall', '가문 집결소', 540, 114, NULL, NULL, 14, 118, 32, 22, 32, 20, NULL, NULL, NULL, 70, 54, '["house-bound","frost-hardened","quiet-step"]', '["arc-clan-crossbow-skirmishers","arc-net-casting-crews","arc-warm-bench-aid-crews"]', 'Rope-hauled sleds carrying boarding hooks and short axes, pulled by teams of skaters. The sleds need no fuel.', '스케이트 신은 조원들이 줄로 끄는 썰매에 승선 갈고리와 짧은 도끼를 싣는다. 썰매는 연료가 들지 않는다.', 'Six layers: a quilted coat under a felt overcoat, padded trousers and wrapped boots, with a hood and goggles and a clan band on the upper arm.', '여섯 겹이다. 누빔 웃옷 위에 펠트 외투를 입고, 솜바지에 감싼 장화를 신으며, 두건과 보안경을 쓰고 위팔에 가문 색 띠를 맨다.', NULL);
INSERT INTO wiki_unit (id, faction_id, sort, name, name_ko, category, role, tier, recruit_building, recruit_building_ko, cost, upkeep, unit_cap, scarce_input, squad_size, hp, melee_attack, melee_defence, weapon_strength, armour, missile_damage, range, ammo, speed, leadership, attributes, counters, equipment, equipment_ko, appearance, appearance_ko, gdd_ref) VALUES ('arc-baptised-spring-legs', 'arc', 170, 'Baptised Spring Legs', '세례 용수철다리대', 'fast', 'shock', 3, 'Baptism Training Hall', '세례 수련장', 1050, 262, 4, 'implants', 10, 150, 44, 30, 46, 38, NULL, NULL, NULL, 80, 68, '["baptised","thin-clad"]', '["arc-baptised-eye-marksmen","arc-field-fitters"]', 'Spring-driven replacement legs for long running leaps, and short axes for the landing. A spare knee joint is strapped to every belt.', '긴 도약을 하는 용수철 대체 다리와, 내려앉는 순간 쓰는 짧은 도끼를 든다. 허리띠마다 예비 무릎 관절이 매여 있다.', 'Three thin layers: a knitted undershirt, a short coat cut open at both knees, and insulating sleeves strapped tight over the legs. The part count is stitched on the right collar.', '얇은 세 겹이다. 뜨개 속옷 위에 양 무릎을 터 놓은 짧은 외투를 입고, 다리 위에 단열 토시를 가죽끈으로 바짝 여민다. 오른쪽 깃에 부위 수를 수놓는다.', NULL);
INSERT INTO wiki_unit (id, faction_id, sort, name, name_ko, category, role, tier, recruit_building, recruit_building_ko, cost, upkeep, unit_cap, scarce_input, squad_size, hp, melee_attack, melee_defence, weapon_strength, armour, missile_damage, range, ammo, speed, leadership, attributes, counters, equipment, equipment_ko, appearance, appearance_ko, gdd_ref) VALUES ('arc-relic-tracked-carrier', 'arc', 180, 'Relic Tracked Carrier', '유물 궤도 운반차', 'war-machine', 'armour', 5, 'Relic Machine Shed', '유물 기계고', 2800, 700, 1, 'fuel,parts', 1, 6200, 35, 30, 280, 110, NULL, NULL, NULL, 38, 90, '["irreplaceable","iron-dread"]', '["arc-clan-head-guard","arc-house-shield-bearers","arc-clan-levy-carbines"]', 'A salvaged armoured hull on rebuilt tracks, with a ramming plough on the front, kept running by a bench crew of fitters. It carries no gun, only plate and weight.', '고쳐 만든 궤도 위에 앞쪽 쟁기 충각을 단 건져 온 장갑 차체이며, 정비 조원들이 굴려 간다. 포는 없고 판금과 무게뿐이다.', 'A rust-streaked hull wrapped in felt and canvas against the cold, with house-red bands painted across the plough. Its crew of four wear two layers, a quilted coat and a hooded cap, because they ride behind heated plates.', '녹물이 흘러내린 차체를 추위에 맞서 펠트와 천막천으로 감싸고, 쟁기 위로 붉은 가문 띠를 칠했다. 조원 넷은 데운 판 뒤에 타기 때문에 누빔 웃옷과 두건 모자 두 겹만 입는다.', NULL);
INSERT INTO wiki_unit (id, faction_id, sort, name, name_ko, category, role, tier, recruit_building, recruit_building_ko, cost, upkeep, unit_cap, scarce_input, squad_size, hp, melee_attack, melee_defence, weapon_strength, armour, missile_damage, range, ammo, speed, leadership, attributes, counters, equipment, equipment_ko, appearance, appearance_ko, gdd_ref) VALUES ('arc-revived-relic-walker', 'arc', 190, 'Revived Relic Walker', '되살린 유물 보행기', 'war-machine', 'armour', 5, 'Relic Machine Shed', '유물 기계고', 3000, 750, 1, 'fuel,parts', 1, 8800, 50, 36, 340, 125, NULL, NULL, NULL, 30, 100, '["irreplaceable","iron-dread"]', '["arc-clan-head-guard","arc-baptised-clan-guard","arc-clan-levy-hooks"]', 'An old two-legged war machine brought back to work by years of bench repair, with a heavy cutting arm and a crushing foot. If it is lost, it cannot be rebuilt.', '수년의 정비로 다시 일하게 된 옛 두 발 전쟁 기계이며, 무거운 절단 팔과 짓누르는 발을 갖췄다. 잃으면 다시 만들지 못한다.', 'A tall patched frame hung with felt blankets and heat wraps over its joints, with house-red bands painted on the legs. The tending crew of six work in two layers beside the warm vents.', '키 큰 기운 틀의 이음매마다 펠트 담요와 열 감싸개를 걸치고, 다리에 붉은 가문 띠를 칠했다. 돌보는 조원 여섯은 따뜻한 배기구 곁에서 두 겹만 입고 일한다.', NULL);
INSERT INTO wiki_unit (id, faction_id, sort, name, name_ko, category, role, tier, recruit_building, recruit_building_ko, cost, upkeep, unit_cap, scarce_input, squad_size, hp, melee_attack, melee_defence, weapon_strength, armour, missile_damage, range, ammo, speed, leadership, attributes, counters, equipment, equipment_ko, appearance, appearance_ko, gdd_ref) VALUES ('arc-net-casting-crews', 'arc', 200, 'Net Casting Crews', '그물 투척조', 'support', 'countermeasure', 1, 'House Repair Shop', '가문 정비소', 210, 44, NULL, NULL, 12, 70, 14, 16, 18, 8, NULL, NULL, NULL, 34, 44, '["net-casting","house-bound"]', '["arc-relic-tracked-carrier","arc-revived-relic-walker"]', 'Weighted nets on long poles for dragging down flying machines and snagging tracks, with hooked knives for cutting free. They need no ammunition.', '날아다니는 기계를 끌어내리고 궤도에 걸어 잡는 추 달린 그물과 긴 장대, 풀어낼 때 쓰는 갈고리 칼을 든다. 탄약은 필요 없다.', 'Four layers: a quilted coat, a leather apron, padded trousers and wrapped boots, with a clan band on the upper arm and a roll of net carried on the back.', '네 겹이다. 누빔 웃옷, 가죽 앞치마, 솜바지, 감싼 장화를 입고, 위팔에 가문 색 띠를 맨고 등에 그물 말이를 진다.', NULL);
INSERT INTO wiki_unit (id, faction_id, sort, name, name_ko, category, role, tier, recruit_building, recruit_building_ko, cost, upkeep, unit_cap, scarce_input, squad_size, hp, melee_attack, melee_defence, weapon_strength, armour, missile_damage, range, ammo, speed, leadership, attributes, counters, equipment, equipment_ko, appearance, appearance_ko, gdd_ref) VALUES ('arc-warm-bench-aid-crews', 'arc', 210, 'Warm Bench Aid Crews', '온기 정비대 구호조', 'support', 'medic', 2, 'House Repair Shop', '가문 정비소', 540, 115, NULL, 'medicine', 12, 72, 12, 16, 18, 6, NULL, NULL, NULL, 34, 52, '["house-bound","field-dressing"]', '["arc-relic-tracked-carrier"]', 'Stretchers, heated blankets and a tin of dressings and cold-weather medicine for each crew. They carry the wounded to the nearest warm bench.', '조마다 들것, 데운 담요, 붕대와 한파용 약품 통을 지닌다. 부상자를 가장 가까운 따뜻한 정비대로 옮긴다.', 'Four layers: a quilted shirt, a heavy apron, padded trousers and felt boots, with a clan-coloured armband and a pouch of dressings at the hip.', '네 겹이다. 누빔 셔츠에 두꺼운 앞치마를 두르고, 솜바지와 펠트 장화를 신으며, 가문 색 완장을 차고 허리에 붕대 주머니를 단다.', NULL);
INSERT INTO wiki_unit (id, faction_id, sort, name, name_ko, category, role, tier, recruit_building, recruit_building_ko, cost, upkeep, unit_cap, scarce_input, squad_size, hp, melee_attack, melee_defence, weapon_strength, armour, missile_damage, range, ammo, speed, leadership, attributes, counters, equipment, equipment_ko, appearance, appearance_ko, gdd_ref) VALUES ('arc-field-fitters', 'arc', 220, 'Field Fitters', '야전 정비조', 'support', 'engineer', 3, 'Body Repair Hall', '몸 정비청', 960, 240, 4, 'implants', 8, 100, 16, 22, 24, 30, NULL, NULL, NULL, 32, 62, '["baptised","field-repair","field-dressing"]', '["arc-relic-tracked-carrier","arc-revived-relic-walker"]', 'Tool rolls, spare joints wrapped in oilcloth and a small heated case for parts that can''t freeze. Each fitter works on a machine or a warrior in the field with one hand free for the straps.', '연장 두루마리, 기름천에 싼 예비 관절, 얼면 안 되는 부품을 넣는 작은 보온 상자를 든다. 정비공은 끈을 만질 한 손을 비워 두고 전장에서 기계나 전사를 고친다.', 'Three layers: a heavy apron over a quilted shirt, rolled sleeves with flapped openings over their own implants, and a clan band on the upper arm. The part count is stitched on the right collar, and insulating sleeves cover the fitter''s own parts on the surface.', '세 겹이다. 누빔 셔츠 위에 두꺼운 앞치마를 두르고, 자기 이식 부위 위에 덮개 틈을 낸 걷은 소매를 입으며, 위팔에 가문 색 띠를 맨다. 오른쪽 깃에 부위 수를 수놓고, 지상에서는 단열 토시가 정비공 자신의 부위를 덮는다.', NULL);
